"use client";

import { useEffect, useId, useRef, useState, type FormEvent, type ReactNode } from "react";
import Link from "next/link";
import { QRCodeSVG } from "qrcode.react";
import { ArrowLeft, ArrowRight, ArrowClockwise, BookOpen, Check, CheckCircle, Circle, Copy, Crown, Eye, EyeSlash, GearSix, HandPalm, Heart, Hourglass, LockKey, MaskHappy, Moon, MusicNotes, Pause, Play, Plus, QrCode, Shield, SignOut, Skull, SpeakerHigh, Sun, Translate, Trash, Users, WarningCircle, WifiHigh, WifiSlash, X } from "@phosphor-icons/react";
import catalogueData from "@/public/assets/werewolf/roles.json";
import { useWerewolfRoom, type Action, type Catalogue, type Command, type GameView, type Language, type Localized, type Role, type Settings } from "@/lib/werewolfClient";
import { WerewolfAudio } from "@/lib/werewolfAudio";
import styles from "./werewolf.module.css";

const catalogue = catalogueData as Catalogue;
const roleMap = Object.fromEntries(catalogue.roles.map((role) => [role.id, role]));
const stepLabels: Record<string, Localized> = {
  afterVote: { en: "The village has decided", zh: "村庄已做出决定" },
  lobby: { en: "Gather your village", zh: "召集你的村庄" }, opening: { en: "The first secrets", zh: "首夜身份行动" }, wolves: { en: "Werewolves, wake up", zh: "狼人请睁眼" }, seer: { en: "Seer, wake up", zh: "预言家请睁眼" }, witch: { en: "Witch, wake up", zh: "女巫请睁眼" }, guard: { en: "Guard, wake up", zh: "守卫请睁眼" }, discussion: { en: "The village has the floor", zh: "天亮了，请发言" }, exile: { en: "Who do you suspect?", zh: "请投票放逐" }, sheriff: { en: "Elect your sheriff", zh: "警长竞选" }, shoot: { en: "One last shot", zh: "请发动开枪技能" }, finished: { en: "The truth comes out", zh: "真相揭晓" }, dawn: { en: "Day breaks", zh: "天亮了" }, night: { en: "Night falls", zh: "天黑请闭眼" }, day: { en: "The village has the floor", zh: "天亮了，请发言" }, voting: { en: "Cast your vote", zh: "请投票" }, reaction: { en: "A final decision", zh: "最后的选择" }, gravekeeper: { en: "Gravekeeper, wake up", zh: "守墓人请睁眼" }, dreamweaver: { en: "Dreamweaver, wake up", zh: "摄梦人请睁眼" }, magician: { en: "Magician, wake up", zh: "魔术师请睁眼" }, raven: { en: "Raven, wake up", zh: "乌鸦请睁眼" }, demonHunter: { en: "Demon Hunter, wake up", zh: "猎魔人请睁眼" }, wolfBeauty: { en: "Wolf Beauty, wake up", zh: "狼美人请睁眼" }, gargoyle: { en: "Gargoyle, wake up", zh: "石像鬼请睁眼" }, pureWhite: { en: "Pure White Seer, wake up", zh: "纯白之女请睁眼" }, wolfWitch: { en: "Wolf Witch, wake up", zh: "狼巫请睁眼" }, piper: { en: "Piper, wake up", zh: "吹笛者请睁眼" }, badge: { en: "Pass the sheriff badge", zh: "移交警徽" }, vote: { en: "Cast your vote", zh: "请投票" }, firstNight: { en: "The first night", zh: "第一个夜晚" }, resolve: { en: "The night is ending", zh: "结算夜间行动" }, hunter: { en: "Hunter, take your shot", zh: "猎人请开枪" }, sheriffVote: { en: "Elect your sheriff", zh: "警长竞选" }, exileVote: { en: "Who do you suspect?", zh: "请投票放逐" }, nightResult: { en: "Day breaks", zh: "天亮了" }, gameOver: { en: "The truth comes out", zh: "真相揭晓" }, bloodMoon: { en: "A blood moon rises", zh: "血月降临" }, copied: { en: "Copied abilities", zh: "复制技能行动" }, mechanicalWolf: { en: "Mechanical Wolf, wake up", zh: "机械狼请睁眼" }, lovers: { en: "Lovers, meet each other", zh: "情侣请相认" }, charm: { en: "A secret enchantment", zh: "秘密魅惑" }, end: { en: "The truth comes out", zh: "真相揭晓" },
};
const choiceLabels: Record<string, Localized> = { save: { en: "Use antidote", zh: "使用解药" }, antidote: { en: "Use antidote", zh: "使用解药" }, poison: { en: "Use poison", zh: "使用毒药" }, inspect: { en: "Inspect", zh: "查验" }, skip: { en: "Do nothing", zh: "不使用技能" }, village: { en: "Village", zh: "好人阵营" }, wolf: { en: "Werewolves", zh: "狼人阵营" }, none: { en: "No ability", zh: "不使用技能" }, protect: { en: "Protect", zh: "守护" }, attack: { en: "Attack", zh: "击杀" }, seer: { en: "Become Seer", zh: "成为预言家" }, guard: { en: "Become Guard", zh: "成为守卫" } };
const winnerLabels: Record<string, Localized> = { village: { en: "The village wins", zh: "好人阵营获胜" }, wolf: { en: "The werewolves win", zh: "狼人阵营获胜" }, lovers: { en: "The lovers win", zh: "情侣阵营获胜" }, piper: { en: "The Piper wins", zh: "吹笛者获胜" }, angel: { en: "The Angel wins", zh: "天使获胜" }, jester: { en: "The Jester wins", zh: "小丑获胜" }, draw: { en: "No one survived", zh: "无人幸存" } };
const errorChinese: Record<string, string> = {
  NOT_SEATED: "此会话已失去座位，请重新申请加入。", SESSION_REPLACED: "此座位已在其他设备恢复，请重新申请加入。", ROOM_NOT_FOUND: "未找到房间，请检查房间码。", ROOM_EXPIRED: "房间已过期，请创建新房间。", INVALID_TOKEN: "会话无效，请重新加入。", EXPIRED_PHASE: "当前阶段计时已结束，正在更新进度，请稍后重试。", STALE_PHASE: "游戏已进入新阶段，请按最新提示操作。", WRONG_PHASE: "当前阶段不能进行此操作。", PAUSED: "牌局已暂停，请等待房主继续。", HOST_ONLY: "此操作仅限房主。", HOST_SEAT: "请先移交房主，再替换此座位。", EMPTY_SEATS: "请为所有预留座位安排玩家后再开始。", INVALID_DECK: "角色配置无效。请确保人数相符、包含狼人和平民阵营，并遵循唯一角色限制。", INVALID_SETTINGS: "请检查计时范围及规则设置。", INVALID_TARGET: "请选择符合条件的目标。", INVALID_ACTION: "请选择可用的技能或跳过行动。", INVALID_NAME: "请输入1–24字的有效名字。", NO_ABILITY: "你在当前阶段没有这项技能。", NO_VOTE: "你当前没有投票权。", PLAYER_COUNT: "游戏需要6–24名玩家。", ROOM_FULL: "房间最多支持24个座位。", REPLACEMENT_REQUIRED: "游戏进行中请选择原有座位进行接替。", REQUEST_EXPIRED: "此加入申请已处理或失效。", RATE_LIMIT: "操作频繁，请稍后重试。", ROOM_BUSY: "多人正在操作，请稍后重试。", CHAT_CLOSED: "此阶段无法在当前频道发言。", INVALID_MESSAGE: "消息须包含1–500个字符。", GAME_RUNNING: "请在本局结束后重置游戏。", RECOVERY_SEATED: "此会话已有座位，请使用新的会话恢复房主。", DISABLED: "房间未启用此功能。", connection: "连接中断，游戏已保存。请稍后重试。", "temporarily-unavailable": "房间暂时无法连接，游戏已保存，请稍后重试。", "too-many-requests": "操作频繁，请稍后重试。", "room-not-found": "未找到房间，请检查房间码。", "room-busy": "多人正在操作，请稍后重试。", "invalid-recovery-key": "房主恢复密钥无效，请检查后重试。", "invalid-room-code": "请输入8位房间码。"
};
function text(value: Localized | string | undefined | null, lang: Language): string { return typeof value === "string" ? value : value?.[lang] || ""; }
function roleIcon(role?: Role, size = 24) { return role?.team === "wolf" ? <Skull size={size} /> : role?.team === "independent" ? <MaskHappy size={size} /> : role?.id === "seer" ? <Eye size={size} /> : role?.id === "guard" ? <Shield size={size} /> : <Moon size={size} />; }
function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) {
  const ref = useRef<HTMLDialogElement>(null);
  const titleId = useId();
  useEffect(() => { ref.current?.showModal(); }, []);
  return <dialog ref={ref} className={styles.modal} aria-labelledby={titleId} onCancel={onClose}><div className={styles.modalHeading}><h2 id={titleId}>{title}</h2><button className={styles.iconButton} onClick={onClose} aria-label="Close / 关闭"><X size={22} /></button></div>{children}</dialog>;
}

export default function WerewolfApp() {
  const room = useWerewolfRoom();
  const [lang, setLang] = useState<Language>("en");
  const [entry, setEntry] = useState<"create" | "join" | "recover">("create");
  const [name, setName] = useState("");
  const [code, setCode] = useState("");
  const [recovery, setRecovery] = useState("");
  const [modal, setModal] = useState<"library" | "settings" | "people" | "recovery" | "rules" | "leave" | "invite" | null>(null);
  const [revealedKey, setRevealedKey] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const [inviteUrl, setInviteUrl] = useState("");
  const [copyFailed, setCopyFailed] = useState(false);
  const [tab, setTab] = useState<"events" | "chat">("events");
  const [audioEnabled, setAudioEnabled] = useState(false);
  const [musicEnabled, setMusicEnabled] = useState(false);
  const [audioError, setAudioError] = useState("");
  const audioRef = useRef<WerewolfAudio | null>(null);
  const [now, setNow] = useState(0);
  const view = room.view;
  const identityKey = `${view?.code}:${view?.status}:${view?.me?.seatId}:${view?.me?.roleId}`;
  const revealed = revealedKey === identityKey;
  const setRevealed = (show: boolean) => setRevealedKey(show ? identityKey : null);
  const t = (en: string, zh: string) => lang === "en" ? en : zh;
  useEffect(() => {
    const frame = requestAnimationFrame(() => {
    try { if (localStorage.getItem("nightfall.language") === "zh") setLang("zh"); } catch { /* no-op */ }
    const queryCode = new URLSearchParams(window.location.search).get("room");
    if (queryCode) { setCode(queryCode.toUpperCase()); setEntry("join"); }
    setNow(Date.now());
    });
    const interval = setInterval(() => setNow(Date.now()), 1000);
    return () => { cancelAnimationFrame(frame); clearInterval(interval); };
  }, []);
  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;
    audio.configure({ voice: audioEnabled, music: musicEnabled, language: lang, active: !!view?.isHost && room.connectivity === "online" });
    if (view?.phase) audio.updatePhase(view.phase);
  }, [audioEnabled, musicEnabled, lang, view?.isHost, view?.phase, room.connectivity]);
  useEffect(() => () => { audioRef.current?.dispose(); audioRef.current = null; }, []);
  const changeAudio = (voice: boolean, music: boolean) => {
    setAudioEnabled(voice); setMusicEnabled(music); setAudioError("");
    if (!audioRef.current) audioRef.current = new WerewolfAudio((status) => setAudioError((status === "error" || status === "locked") ? "unavailable" : ""));
    const audio = audioRef.current;
    audio.configure({ voice, music, language: lang, active: !!view?.isHost && room.connectivity === "online" });
    // Unlock directly in the opt-in gesture, before awaiting any work.
    if (voice || music) void audio.unlock().then(() => { if (view?.phase) audio.updatePhase(view.phase); }).catch(() => setAudioError("unavailable"));
  };
  const toggleLanguage = () => { const next = lang === "en" ? "zh" : "en"; setLang(next); try { localStorage.setItem("nightfall.language", next); } catch { /* no-op */ } };
  const send = (command: Command) => room.command({ expectedPhaseId: view?.phase.id, ...command });
  const enterRoom = (event: FormEvent) => { event.preventDefault(); void room.enter(entry, name, code, recovery); };
  const showInvite = () => {
    if (!view) return;
    setInviteUrl(`${window.location.origin}/werewolf/?room=${view.code}`);
    setModal("invite");
  };
  const share = async () => {
    if (!view) return;
    setCopyFailed(false);
    try {
      await navigator.clipboard.writeText(`${window.location.origin}/werewolf/?room=${view.code}`);
      setCopied(true); setTimeout(() => setCopied(false), 2200);
    } catch { setCopyFailed(true); showInvite(); }
  };
  const disabled = !!room.busy || room.connectivity !== "online" || room.sessionExpired;
  const connected = view?.seats.filter((seat) => seat.occupied).length || 0;
  const remaining = view?.phase.deadline ? Math.max(0, Math.ceil((view.phase.deadline - now - (view.clockOffset || 0)) / 1000)) : null;
  const title = view ? text(stepLabels[view.phase.step] || stepLabels[view.phase.kind], lang) : "";
  const role = view?.me?.roleId ? roleMap[view.me.roleId] : undefined;
  return <main className={styles.app} lang={lang === "zh" ? "zh-CN" : "en"}>
    <header className={styles.header}>
      <Link href="/" className={styles.backLink} aria-label={t("Back to website", "返回网站")}><ArrowLeft size={18} /></Link>
      <a href="/werewolf/" className={styles.wordmark}><Moon size={25} weight="duotone" /><span>NIGHTFALL<small>狼人杀 · WEREWOLF</small></span></a>
      <nav className={styles.headerActions} aria-label={t("Game navigation", "游戏导航")}>
        <button className={styles.navButton} onClick={() => setModal("rules")}><BookOpen size={17} /><span>{t("How to play", "游戏规则")}</span></button>
        <button className={styles.navButton} onClick={() => setModal("library")}><MaskHappy size={18} /><span>{t("Role library", "角色图鉴")}</span></button>
        <button className={styles.languageButton} onClick={toggleLanguage}><Translate size={17} />{lang === "en" ? "中文" : "English"}</button>
      </nav>
    </header>
    {room.error && <div className={styles.error} role="alert"><WarningCircle size={20} /><span>{t("The action could not be completed.", "操作未能完成。")}{" "}{(lang === "en" ? room.error.message : errorChinese[room.error.code] || "请检查房间、身份或当前阶段后重试。")}</span><button onClick={room.clearError} aria-label={t("Dismiss", "关闭")}><X size={18} /></button></div>}
    {room.sessionExpired && <div className={styles.connectionBanner} role="alert"><WarningCircle size={20} /><span>{t("This session no longer owns a seat. Join again; host approval is needed if the game has started.", "此会话已不再拥有座位，请重新加入。如果游戏已经开始，则需房主批准。")}</span><button onClick={() => { setCode(room.session?.code || ""); setName(room.session?.name || ""); setEntry("join"); room.disconnect(true); }}>{t("Rejoin room", "重新加入房间")}</button></div>}
    {room.session && !room.sessionExpired && room.connectivity !== "online" && <div className={styles.connectionBanner} role="status"><WifiSlash size={19} /><span>{t("Reconnecting to your table. Your identity and progress are saved; controls will return when connected.", "正在重新连接。身份和进度已保存，连接恢复后可继续操作。")}</span><button onClick={room.retry}>{t("Retry now", "立即重试")}</button></div>}
    {!view && !room.session && <div className={styles.entryLayout}>
      <section className={styles.introduction}>
        <span className={styles.eyebrow}><span className={styles.redLine} />{t("A game of trust. And betrayal.", "信任与谎言之间。")}</span>
        <h1>{t("Everyone has", "每个人，")}<br />{t("a secret.", "都有秘密。")}</h1>
        <p className={styles.introCopy}>{t("Bring your friends to the table. The village falls asleep. The wolves wake up. Who will you believe?", "邀好友入座。天黑请闭眼，狼人请睁眼。今夜，你会相信谁？")}</p>
        <div className={styles.roleFan} aria-hidden="true"><div><Shield size={37} weight="duotone" /><span>{t("THE GUARD", "守卫")}</span></div><div><Skull size={56} weight="duotone" /><span>{t("THE WEREWOLF", "狼人")}</span></div><div><Eye size={37} weight="duotone" /><span>{t("THE SEER", "预言家")}</span></div></div>
        <div className={styles.entryFacts}><span><Users size={17} />{t("6–24 players", "6–24 名玩家")}</span><span><Translate size={17} />English / 中文</span><span><Moon size={17} />{t(`${catalogue.roles.length} playable roles`, `${catalogue.roles.length} 种可玩角色`)}</span></div>
      </section>
      <section className={styles.entryPanel} aria-label={t("Enter a game", "进入游戏")}>
        <div className={styles.entryTabs}><button className={entry === "create" ? styles.activeTab : ""} onClick={() => setEntry("create")}>{t("Create a room", "创建房间")}</button><button className={entry !== "create" ? styles.activeTab : ""} onClick={() => setEntry("join")}>{t("Join a room", "加入房间")}</button></div>
        <div className={styles.entryFormHeading}><h2>{entry === "create" ? t("Your table awaits.", "好戏，等你开场。") : entry === "recover" ? t("Take back your table.", "找回你的房间。") : t("Take your seat.", "请入座。")}</h2><p>{entry === "create" ? t("You’re the host. Invite friends, choose your roles, and set the night in motion.", "成为房主，邀请好友，配置角色，开启这个夜晚。") : entry === "recover" ? t("Use the private recovery key saved when you created this room.", "输入创建房间时保存的私人恢复密钥。") : t("Enter your name to join the lobby instantly. After the game starts, the host approves new devices and seat replacements.", "输入名字即可直接加入大厅。游戏开始后，新设备加入或接替原座位须由房主批准。")}</p></div>
        <form onSubmit={enterRoom} className={styles.entryForm}>
          <label>{t("Your name", "你的名字")}<input value={name} onChange={(event) => setName(event.target.value)} required maxLength={24} autoComplete="nickname" placeholder={t("What should we call you?", "怎么称呼你？")} /></label>
          {entry !== "create" && <label>{t("Room code", "房间码")}<input value={code} onChange={(event) => setCode(event.target.value.toUpperCase().replace(/[^A-F0-9]/g, ""))} required maxLength={8} minLength={8} pattern="[A-F0-9]{8}" autoCapitalize="characters" placeholder="A1B2C3D4" className={styles.codeInput} /></label>}
          {entry === "recover" && <label>{t("Host recovery key", "房主恢复密钥")}<input value={recovery} onChange={(event) => setRecovery(event.target.value)} required autoComplete="off" type="password" /></label>}
          <button className={styles.primaryButton} disabled={!!room.busy || !room.restored} type="submit">{room.busy ? t("Connecting…", "连接中…") : entry === "create" ? t("Create room", "创建房间") : entry === "recover" ? t("Recover host access", "恢复房主权限") : t("Join room", "加入房间")}<ArrowRight size={19} /></button>
        </form>
        <p className={styles.privateNote}><LockKey size={15} />{t("Private rooms. Secret identities. No account needed.", "私人房间 · 秘密身份 · 无需注册")}</p>
        <button className={styles.textButton} onClick={() => setEntry(entry === "recover" ? "join" : "recover")}>{entry === "recover" ? t("Back to joining", "返回加入房间") : t("Recover a room you hosted", "恢复我创建的房间")}</button>
      </section>
    </div>}
    {!view && room.session && <div className={styles.loading}><Moon size={44} /><h1>{t("Finding your table…", "正在返回房间…")}</h1><p>{t("Restoring your private seat and the latest game state.", "正在恢复你的身份与最新游戏进度。")}</p><button className={styles.secondaryButton} onClick={() => room.disconnect()}>{t("Return to room selection", "返回房间选择")}</button></div>}
    {view && <div className={styles.roomLayout}>
      <div className={styles.roomBar}><div><span className={styles.eyebrow}>{t("PRIVATE TABLE", "私人牌局")}</span><button className={styles.roomCode} onClick={share} title={t("Copy invitation link", "复制邀请链接")}>{view.code}{copied ? <Check size={19} /> : <Copy size={19} />}</button></div><div className={styles.roomBarActions}><span className={`${styles.connectionState} ${room.connectivity === "online" ? styles.isOnline : ""}`}>{room.connectivity === "online" ? <WifiHigh size={15} /> : <WifiSlash size={15} />}{room.connectivity === "online" ? t("Connected", "已连接") : t("Reconnecting", "重连中")}</span><button className={styles.secondaryButton} onClick={showInvite}><QrCode size={18} />{t("Invite / QR code", "邀请 / 二维码")}</button>{view.isHost && <button className={styles.iconButton} onClick={() => setModal("settings")} aria-label={t("Room settings", "房间设置")}><GearSix size={21} /></button>}<button className={styles.iconButton} onClick={() => setModal("leave")} aria-label={t("Leave room", "离开房间")}><SignOut size={21} /></button></div></div>
      <div className={styles.gameColumns}>
        <section className={styles.tablePanel}>
          <div className={styles.phaseHeading}><div className={styles.phaseIcon}>{view.phase.kind === "night" || view.status === "lobby" ? <Moon size={26} weight="duotone" /> : view.phase.kind === "voting" ? <HandPalm size={25} /> : <Sun size={27} />}</div><div><span className={styles.eyebrow}>{view.status === "lobby" ? t("THE LOBBY", "等候大厅") : view.status === "finished" ? t("GAME OVER", "游戏结束") : `${view.phase.kind === "night" ? t("NIGHT", "夜晚") : t("DAY", "白天")} ${view.phase.kind === "night" ? view.phase.number || 1 : view.day || 1}`}</span><h1>{title}</h1></div>{remaining !== null && view.status === "playing" && <div className={styles.timer}><Hourglass size={16} /><span>{view.phase.paused ? t("Paused", "已暂停") : `${Math.floor(remaining / 60)}:${String(remaining % 60).padStart(2, "0")}`}</span></div>}</div>
          {view.phase.paused && <div className={styles.notice}><Pause size={18} />{t("The table is paused. The host can resume when everyone is ready.", "牌局已暂停，所有人准备好后房主可继续游戏。")}</div>}
          {!view.me && <div className={styles.pendingNotice}><Hourglass size={20} /><div><strong>{view.status === "lobby" ? t("Waiting for a free seat", "等待空余座位") : t("Your seat is waiting for approval", "正在等待房主安排座位")}</strong><p>{view.status === "lobby" ? t("This lobby is full. You’ll join automatically when a seat becomes available.", "大厅已满。出现空余座位后，你将自动加入。") : t("Your host can restore an existing seat, including its original role and history.", "房主可安排你接替已有座位，保留其原有身份与历史。")}</p></div></div>}
          <div className={styles.seatArea}>
            <div className={styles.tableWatermark} aria-hidden="true"><Moon size={70} weight="thin" /><span>NIGHTFALL</span><small>{t("TRUST NO ONE", "谁值得相信")}</small></div>
            <div className={styles.seatGrid}>{Array.from({ length: Math.max(view.seats.length, view.status === "lobby" ? Math.min(12, Math.max(6, view.roleDeck.length)) : 0) }, (_, index) => {
              const seat = view.seats[index];
              return seat ? <div key={seat.id} className={`${styles.seat} ${!seat.alive && view.status !== "lobby" ? styles.deadSeat : ""} ${seat.id === view.me?.seatId ? styles.mySeat : ""} ${seat.id === view.speakerSeatId ? styles.speakingSeat : ""}`}><div className={styles.avatar}>{!seat.alive && view.status !== "lobby" ? <Skull size={25} /> : <span>{(Array.from(seat.name)[0] || "?").toUpperCase()}</span>}<span className={`${styles.presence} ${seat.connected && seat.occupied ? styles.present : ""}`} title={seat.connected ? t("Connected", "在线") : t("Disconnected — seat saved", "已断线，座位保留")} />{seat.isHost && <Crown size={16} weight="fill" className={styles.hostCrown} />}</div><span className={styles.seatNumber}>{String(index + 1).padStart(2, "0")}</span><strong>{seat.name}{seat.id === view.me?.seatId && <small> {t("(you)", "（你）")}</small>}</strong><span className={styles.seatStatus}>{seat.isSheriff ? t("Sheriff", "警长") : !seat.occupied ? t("Seat reserved", "等待接替") : !seat.connected ? t("Reconnecting", "离线，待重连") : view.status === "lobby" ? t("At the table", "已入座") : seat.alive ? seat.id === view.speakerSeatId ? t("Speaking", "正在发言") : t("Alive", "存活") : t("Eliminated", "已出局")}</span>{seat.roleId && <span className={styles.revealedSeatRole}>{text(roleMap[seat.roleId]?.name, lang)}</span>}</div> : <button key={`empty-${index}`} className={`${styles.seat} ${styles.emptySeat}`} onClick={() => view.isHost ? setModal("people") : showInvite()}><div className={styles.avatar}><Plus size={22} /></div><span className={styles.seatNumber}>{String(index + 1).padStart(2, "0")}</span><strong>{t("Empty seat", "虚位以待")}</strong><span className={styles.seatStatus}>{t("Invite a friend", "邀请好友")}</span></button>;
            })}</div>
          </div>
          <div className={styles.tableFooter}><span><Users size={17} />{connected} {t("at the table", "人已入座")}{view.status !== "lobby" && ` · ${view.seats.filter((seat) => seat.alive).length} ${t("alive", "人存活")}`}</span><button className={styles.textButton} onClick={() => setModal("library")}>{t("View the deck", "查看角色配置")}<ArrowRight size={15} /></button></div>
          {view.status === "finished" && <div className={styles.result}><Crown size={30} /><h2>{text(winnerLabels[typeof view.winner === "string" ? view.winner : view.winner?.team || ""], lang) || t("The game has ended", "本局游戏结束")}</h2><p>{typeof view.winner === "object" && view.winner?.reason ? text(view.winner.reason, lang) : t("Every secret is now on the table. See the game record below.", "所有秘密现已揭晓。下方可查看本局游戏记录。")}</p></div>}
          {view.phase.kind === "voting" && <p className={styles.voteProgress}><HandPalm size={16} />{t(`${view.voteCount || 0} votes submitted. Choices stay hidden until voting closes.`, `已提交 ${view.voteCount || 0} 票，投票结束前不公开选择。`)}</p>}
          {view.lastVote && view.phase.kind !== "voting" && <div className={styles.voteTally}><span>{t("Last vote", "上次投票")}</span>{Object.entries(view.lastVote.tally).map(([id, count]) => <span key={id}>{view.seats.find((seat) => seat.id === id)?.name || id} <strong>{count}</strong></span>)}</div>}
          {view.me && view.status === "playing" && <ActionPanel key={view.phase.id} view={view} lang={lang} disabled={disabled || view.phase.paused} send={send} />}
        </section>
        <aside className={styles.sidebar}>
          <section className={styles.identityPanel}><div className={styles.sectionHeading}><h2><LockKey size={16} />{t("Your identity", "你的身份")}</h2>{role && <button className={styles.iconButton} onClick={() => setRevealed(!revealed)} aria-label={revealed ? t("Hide role", "隐藏身份") : t("Reveal role", "查看身份")}>{revealed ? <EyeSlash size={19} /> : <Eye size={19} />}</button>}</div>
            {role ? <><button className={`${styles.identityCard} ${revealed ? styles.identityRevealed : ""}`} aria-pressed={revealed} onClick={() => setRevealed(!revealed)}>{revealed ? roleIcon(role, 40) : <LockKey size={36} weight="thin" />}<strong>{revealed ? role.name[lang] : t("A secret worth keeping", "你的秘密身份")}</strong><span>{revealed ? role.name[lang === "en" ? "zh" : "en"] : t("Tap to reveal your role", "点击查看身份")}</span></button>{revealed && <><p className={styles.roleDescription}>{role.description[lang]}</p>{!!view.me?.allies.length && <p className={styles.allies}><Heart size={15} />{t("Known allies:", "已知同伴：")} {view.me.allies.map((id) => view.seats.find((seat) => seat.id === id)?.name).filter(Boolean).join(" · ")}</p>}{view.me?.privateLog.map((event, index) => <p key={event.id || index} className={styles.privateLog}>{text(event.text, lang)}</p>)}</>}</> : <div className={styles.hiddenIdentity}><Moon size={33} weight="thin" /><p>{t("Your story begins when the host deals the roles.", "房主发牌后，你的故事即将开始。")}</p></div>}
          </section>
          {view.isHost && <section className={styles.hostPanel}><div className={styles.sectionHeading}><h2><Crown size={17} />{t("Host controls", "房主控制")}</h2><button className={styles.iconButton} onClick={() => setModal("settings")} aria-label={t("Settings", "设置")}><GearSix size={18} /></button></div>
            {!!view.requests?.length && <button className={styles.requestAlert} onClick={() => setModal("people")}><Users size={18} />{view.requests.length} {t("waiting to join", "人等待加入")}<ArrowRight size={16} /></button>}
            {view.status === "lobby" ? <><button className={styles.primaryButton} disabled={disabled || view.seats.length < 6 || (view.roleDeck.length > 0 && view.roleDeck.length !== view.seats.length) || view.seats.some((seat) => !seat.occupied)} onClick={() => void send({ type: "startGame" })}><Play size={18} weight="fill" />{t("Deal roles & begin", "发牌并开始")}</button><p className={styles.hint}>{view.roleDeck.length === 0 ? t("A balanced deck is chosen automatically, or choose your own in settings.", "将自动选择平衡配置，也可在设置中自定义。") : view.roleDeck.length !== view.seats.length ? t(`${view.roleDeck.length} role cards · ${view.seats.length} players. Match the deck to your table in settings.`, `${view.roleDeck.length} 张身份牌 · ${view.seats.length} 名玩家，请在设置中匹配人数。`) : t("At least 6 players. Everyone receives their role privately.", "至少6人，每位玩家将单独收到身份。")}</p></> : view.status === "finished" ? <button className={styles.primaryButton} disabled={disabled} onClick={() => void send({ type: "resetGame" })}><ArrowClockwise size={18} />{t("Return to lobby", "返回大厅")}</button> : <><div className={styles.hostButtons}>{view.phase.kind === "day" && <><button className={styles.primaryButton} disabled={disabled || view.phase.paused} onClick={() => void send({ type: "startVoting" })}><HandPalm size={17} />{t("Start voting", "开始投票")}</button><button className={styles.secondaryButton} disabled={disabled || view.phase.paused} onClick={() => void send({ type: "startNight" })}><Moon size={17} />{t("Next night", "进入夜晚")}</button>{view.settings.sheriff && <button className={styles.secondaryButton} disabled={disabled || view.phase.paused} onClick={() => void send({ type: "startSheriff" })}><Crown size={17} />{t("Sheriff election", "警长竞选")}</button>}</>}{view.phase.kind === "voting" && <button className={styles.primaryButton} disabled={disabled || view.phase.paused} onClick={() => void send({ type: "resolveVoting" })}><CheckCircle size={17} />{t("Close & count votes", "结束并统计投票")}</button>}{(view.phase.kind === "night" || view.phase.kind === "reaction") && <button className={styles.primaryButton} disabled={disabled || view.phase.paused} onClick={() => void send({ type: "nextPhase" })}>{t("Next step", "进入下一阶段")}<ArrowRight size={18} /></button>}<button className={styles.secondaryButton} disabled={disabled} onClick={() => void send({ type: view.phase.paused ? "resume" : "pause" })}>{view.phase.paused ? <Play size={16} /> : <Pause size={16} />}{view.phase.paused ? t("Resume", "继续游戏") : t("Pause table", "暂停牌局")}</button></div><p className={styles.hint}>{t("Advancing closes this step. Missing actions count as skipped; reconnecting players keep their seat.", "推进阶段会结束当前行动。未提交视为跳过；断线玩家保留座位。")}</p></>}
            <button className={styles.textButton} onClick={() => setModal("recovery")}>{t("Save host recovery key", "保存房主恢复密钥")}</button>
            <button className={styles.manageButton} onClick={() => setModal("people")}><Users size={18} />{t("Manage players & rejoining", "玩家与重连管理")}<ArrowRight size={15} /></button>
          </section>}
          <section className={styles.audioPanel}><div className={styles.sectionHeading}><h2><SpeakerHigh size={17} />{t("At the table", "牌局氛围")}</h2></div><label className={styles.toggleRow}><span><SpeakerHigh size={17} /><span>{t("Brian · voice moderator", "Brian · 语音法官")}<small>{view.isHost ? t("Plays on this device", "仅在此设备播放") : t("Controlled by the host", "由房主设备播放")}</small></span></span><input type="checkbox" checked={audioEnabled} disabled={!view.isHost} onChange={(event) => changeAudio(event.target.checked, musicEnabled)} /></label><label className={styles.toggleRow}><span><MusicNotes size={17} />{t("Night ambience", "夜间氛围音乐")}</span><input type="checkbox" checked={musicEnabled} disabled={!view.isHost} onChange={(event) => changeAudio(audioEnabled, event.target.checked)} /></label>{audioEnabled && view.isHost && <button className={styles.textButton} onClick={() => { void audioRef.current?.unlock(); }}>{t("Replay announcement", "重播本阶段提示")}</button>}{audioError && <p className={styles.warningText}>{t("Audio could not play. Toggle sound off and on to retry, and check this device’s sound settings.", "音频未能播放，请关闭后重新开启，并检查设备的声音设置。")}</p>}<p className={styles.hint}>{t("Use one speaker for an in-person table. Voice never announces secret results.", "线下游戏建议仅开启一台设备的扬声器。语音不会播报私人查验结果。")}</p></section>
        </aside>
      </div>
      <section className={styles.activityPanel}><div className={styles.activityHeading}><div className={styles.activityTabs}><button className={tab === "events" ? styles.activeTab : ""} onClick={() => setTab("events")}>{t("Game record", "游戏记录")}</button><button className={tab === "chat" ? styles.activeTab : ""} onClick={() => setTab("chat")}>{t("Table chat", "牌局聊天")}</button></div><span className={styles.hint}>{t("Private actions stay private", "秘密行动仅自己可见")}</span></div>{tab === "events" ? <div className={styles.eventList}>{view.events.length ? view.events.slice().reverse().slice(0, 50).map((event) => <div key={event.id} className={styles.event}><Circle size={7} weight="fill" /><p>{text(event.text, lang)}</p><time>{new Date(event.at).toLocaleTimeString(lang === "zh" ? "zh-CN" : "en-GB", { hour: "2-digit", minute: "2-digit" })}</time></div>) : <p className={styles.emptyLog}>{t("A quiet village. For now.", "村庄此刻，依然宁静。")}</p>}</div> : <ChatPanel view={view} lang={lang} disabled={disabled} send={send} />}</section>
      {view.status === "finished" && !!view.replay?.length && <Replay view={view} lang={lang} />}
    </div>}
    <footer className={styles.footer}><span>NIGHTFALL <span>·</span> {t("A table full of secrets.", "一桌人，各怀秘密。")}</span><button onClick={() => setModal("rules")}>{t("House rules", "本应用规则")}</button></footer>
    {modal === "invite" && view && inviteUrl && <Modal title={t("Invite to your table", "邀请好友入座")} onClose={() => setModal(null)}>
      <div className={styles.invitePanel}>
        <p>{t("Scan with your phone’s camera, open the link, and enter your name.", "用手机相机扫码，打开链接并输入你的名字。")}</p>
        <div className={styles.qrFrame}><QRCodeSVG value={inviteUrl} size={256} level="M" marginSize={4} bgColor="#ffffff" fgColor="#000000" title={t(`Scan to join room ${view.code}`, `扫码加入房间 ${view.code}`)} role="img" /></div>
        <span className={styles.eyebrow}>{t("ROOM CODE", "房间码")}</span><strong className={styles.inviteCode}>{view.code}</strong>
        <p className={styles.inviteHint}>{view.status === "lobby" ? t("Join and leave freely before the game starts. No host approval needed.", "游戏开始前可自由加入和离开，无需房主批准。") : t("The game has started. The host will approve your request and assign an existing seat.", "游戏已开始。房主批准申请后会安排你接替已有座位。")}</p>
        <button className={styles.primaryButton} onClick={share}>{copied ? <Check size={18} /> : <Copy size={18} />}{copied ? t("Link copied", "链接已复制") : t("Copy invite link", "复制邀请链接")}</button>
        <label className={styles.inviteLink}>{t("Or share this link", "也可分享链接")}<input value={inviteUrl} readOnly onFocus={(event) => event.target.select()} /></label>
        {copyFailed && <span className={styles.hint} role="status">{t("Copy unavailable. Select the link above to copy it manually.", "无法自动复制，请选中上方链接手动复制。")}</span>}
      </div>
    </Modal>}
    {modal === "library" && <RoleLibrary lang={lang} view={view} onClose={() => setModal(null)} />}
    {modal === "settings" && view?.isHost && <RoomSettings view={view} lang={lang} disabled={disabled} send={send} onClose={() => setModal(null)} />}
    {modal === "people" && view && <PeopleManager view={view} lang={lang} disabled={disabled} send={send} onClose={() => setModal(null)} />}
    {modal === "rules" && <Modal title={t("Before night falls", "天黑之前")} onClose={() => setModal(null)}><div className={styles.rules}>{view && <div className={styles.currentRules}><h3>{t("This table’s rules", "本房间规则")}</h3><p>{t("Werewolf victory:", "狼人获胜：")} {view.settings.winCondition === "edge" ? t("Eliminate all villagers OR all village special roles", "屠边：消灭所有平民或所有神职") : view.settings.winCondition === "all" ? t("Eliminate all village players", "屠城：消灭全部好人") : t("Equal or outnumber all opposition", "达到人数优势")}</p><p>{t("Sheriff:", "警长：")} {view.settings.sheriff ? t("enabled", "启用") : t("disabled", "关闭")} · {t("Witch self-save:", "女巫自救：")} {view.settings.witchSelfSave ? t("allowed", "允许") : t("not allowed", "不允许")}</p><p>{t("Guard + antidote:", "同守同救：")} {view.settings.guardAntidote === "save" ? t("target survives", "目标存活") : t("target dies", "目标死亡")} · {t("Automatic phases:", "自动推进：")} {view.settings.autoAdvance ? t("on", "开启") : t("off", "关闭")}</p><p>{t("Sheriff votes count as 1.5. A tied exile vote eliminates nobody unless Scapegoat is present. Final words are managed by the host before advancing.", "警长投票计1.5票。放逐平票无人出局，替罪羊在场时除外。房主可在推进前安排遗言。")}</p></div>}<p>{t("Werewolf is a game of hidden roles, conversation, and deception. Play around the same table or use your preferred voice call alongside the room chat.", "狼人杀是一场关于隐藏身份、讨论和推理的游戏。可以围桌面对面游玩，也可以配合语音通话和房间聊天远程游玩。")}</p><ol><li><strong>{t("Take a secret identity.", "领取秘密身份。")}</strong> {t("The host chooses a deck and deals the cards. Only you see your role.", "房主配置角色并发牌，只有你能看到自己的身份。")}</li><li><strong>{t("Act during the night.", "夜间行动。")}</strong> {t("Follow the private prompts. Choose your target, then submit. Wait quietly during other roles’ turns.", "按照私人提示选择目标并提交，其他角色行动时请安静等待。")}</li><li><strong>{t("Talk during the day.", "白天讨论。")}</strong> {t("Share information, make accusations, or bluff. The host can set a speaker or start the sheriff election.", "分享线索、质疑或伪装。房主可安排发言者，或发起警长竞选。")}</li><li><strong>{t("Vote together.", "进行投票。")}</strong> {t("Choose who to exile. The app resolves abilities, deaths, and the winning faction.", "选择放逐对象，由应用结算技能、死亡与获胜阵营。")}</li></ol><h3>{t("A connection is not an identity", "断线不等于离场")}</h3><p>{t("Before the game starts, anyone with the invitation can join and leave freely. Refreshing or losing connection keeps your seat. Once play starts, join on a new device with your name and ask the host to replace your previous seat. Your role, actions, and history follow the seat. Never share your host recovery key.", "游戏开始前，持有邀请的玩家可自由加入和离开。刷新或断线会保留座位。开始游戏后，更换设备时请用原名字加入，由房主批准接替原座位。身份、技能和历史记录跟随座位保留。请勿分享房主恢复密钥。")}</p><h3>{t("Advanced roles, explicit rules", "进阶角色，明确规则")}</h3><p>{catalogue.ruleset[lang]} {t("This library implements 31 roles, including specified variants of Mechanical Wolf, Thief, and Scapegoat. Roles and variants from other editions can be added later; there is no universal complete roster.", "当前实现31种角色，包括明确说明的机械狼、盗贼及替罪羊变体。未来可继续扩展其他版本角色；狼人杀并不存在统一的全部角色列表。")}</p><p>{t("The host controls pace and seating but cannot see other players’ secret identities. Automatic phase timing is optional. A disconnected player keeps their identity; host approval is required to transfer it to a new device.", "房主可控制进度和座位，但无法查看其他玩家的秘密身份。可选自动推进阶段。断线保留身份，换设备接替需经房主批准。")}</p></div></Modal>}
    {modal === "recovery" && <Modal title={t("Keep your table recoverable", "随时找回你的房间")} onClose={() => setModal(null)}><p>{t("Save this private key somewhere safe. If your device loses its saved session, choose Recover a room on the start screen. Anyone with this key can take over the host seat.", "请妥善保存此私人密钥。如果设备丢失会话，可在首页选择恢复房间。持有此密钥的人可以接管房主座位。")}</p><div className={styles.recoveryBox}><label>{t("Host recovery key", "房主恢复密钥")}<input readOnly value={room.session?.recoveryKey || ""} onFocus={(event) => event.target.select()} /></label></div><p>{t("Room code:", "房间码：")} <strong>{view?.code}</strong></p></Modal>}
    {modal === "leave" && <Modal title={t("Leave the table?", "离开牌局？")} onClose={() => setModal(null)}><p>{view?.status === "lobby" ? t("Your seat will be released. You can join again at any time before the game starts without host approval.", "离开后座位将释放。游戏开始前可随时重新加入，无需房主批准。") : t("Your seat and role stay in the game. Joining this room again on this device restores your saved seat. The host can also assign a replacement.", "座位和身份仍保留在游戏中。在此设备重新加入房间可恢复原座位，房主也可以安排其他人接替。")}</p>{view?.isHost && view.status === "lobby" && <p className={styles.warningText}>{t("Hosting passes to another player. If the lobby becomes empty, the next player to join becomes host. Your old recovery key will no longer work.", "房主权限将移交给另一位玩家。若大厅无人，则下一位加入的玩家成为房主。原恢复密钥将失效。")}</p>}{view?.status === "lobby" && room.connectivity !== "online" && <p role="status">{t("Reconnect to release your seat. Closing the page while offline keeps it reserved for you.", "请恢复连接后离开，以释放座位。离线时关闭页面会保留你的座位。")}</p>}{view?.isHost && view.status !== "lobby" && <p className={styles.warningText}>{t("Your host key stays saved on this device. Keep a copy below if you will switch devices.", "房主密钥会保存在此设备上。如果需要更换设备，请另行保存下方密钥。")}</p>}{view?.isHost && view.status !== "lobby" && room.session?.recoveryKey && <div className={styles.recoveryBox}><label>{t("Private host recovery key", "房主私人恢复密钥")}<input readOnly value={room.session.recoveryKey} /></label></div>}<div className={styles.modalActions}><button className={styles.secondaryButton} onClick={() => setModal(null)}>{t("Stay", "留下")}</button><button className={styles.dangerButton} disabled={!!room.busy || view?.status === "lobby" && room.connectivity !== "online"} onClick={async () => { if (room.connectivity !== "online" || await send({ type: "leave" })) { room.disconnect(); setModal(null); } }}>{t("Leave room", "离开房间")}</button></div></Modal>}
  </main>;
}

function ActionPanel({ view, lang, disabled, send }: { view: GameView; lang: Language; disabled: boolean; send: (command: Command) => Promise<boolean> }) {
  const t = (en: string, zh: string) => lang === "en" ? en : zh;
  const action = view.me?.action;
  const [targets, setTargets] = useState<string[]>([]);
  const [choice, setChoice] = useState("");
  const [special, setSpecial] = useState("");
  const voting = action?.kind === "vote";
  const daySpecial = !view.phase.paused && (view.me?.canDuel || view.me?.canExplode || view.me?.canPassBadge);
  const isDouble = action?.input === "double";
  const available = action?.targets || (voting || daySpecial ? view.seats.filter((seat) => seat.alive && seat.id !== view.me?.seatId).map((seat) => seat.id) : []);
  const select = (id: string) => setTargets((current) => current.includes(id) ? current.filter((target) => target !== id) : isDouble ? [...current.slice(-1), id] : [id]);
  const optionValue = (option: NonNullable<Action["options"]>[number]) => typeof option === "string" ? option : option.value || option.id || "";
  const submit = async (skip = false) => {
    if (voting) await send({ type: "vote", targetId: skip ? null : targets[0] });
    else if (action?.kind === "shoot") await send({ type: "shoot", targetId: skip ? null : targets[0] });
    else if (action?.kind === "passBadge" || action?.kind === "badge") await send({ type: "passBadge", targetId: skip ? null : targets[0] });
    else await send({ type: "nightAction", ability: skip ? "skip" : choice || action?.ability, targetId: skip ? undefined : targets[0], targetIds: skip ? [] : targets, choice: skip ? "skip" : choice || undefined });
  };
  const needsTarget = (action?.input === "single" || action?.input === "double" || voting) && choice !== "save" && choice !== "skip";
  const invalid = needsTarget && targets.length < (action?.minTargets || 1) || !!action?.options?.length && !choice;
  if (!action && !voting && !daySpecial) return <div className={styles.waitingAction}><Moon size={19} /><p>{!view.me?.alive ? t("You have been eliminated. Follow the game and keep its secrets.", "你已出局，请继续观战并保守秘密。") : view.phase.kind === "night" ? t("Keep your eyes closed. Your private prompt appears when it’s your turn.", "请闭眼等待，轮到你时将显示私人行动提示。") : t("Listen closely. The next decision could change everything.", "认真倾听，下一个决定可能改变一切。")}</p></div>;
  return <div className={styles.actionPanel}><div className={styles.sectionHeading}><h2>{voting ? <HandPalm size={20} /> : <Eye size={20} />}{voting ? t("Your vote", "你的投票") : action ? t("Your private action", "你的秘密行动") : t("Daytime ability", "白天技能")}</h2>{action?.alreadySubmitted && <span className={styles.submitted}><CheckCircle size={16} />{t("Submitted · can update", "已提交 · 可修改")}</span>}</div>
    {action?.step === "witch" && <p className={styles.privateLog}>{action.victimId ? t(`The pack targeted ${view.seats.find((seat) => seat.id === action.victimId)?.name}.`, `狼刀目标是 ${view.seats.find((seat) => seat.id === action.victimId)?.name}。`) : t("No victim is visible to you tonight.", "今夜你看不到狼刀目标。")}</p>}
    {action && <p className={styles.actionHelp}>{action.input === "double" ? t("Choose two players, then confirm.", "选择两名玩家后确认。") : action.input === "choice" ? t("Choose how to use your ability.", "请选择技能的使用方式。") : action.input === "none" ? t("Review your private information, then confirm or wait for the next step.", "查看私人信息后确认，或等待进入下一阶段。") : t("Select your target. Your choice stays private until the rules reveal it.", "请选择目标。在规则允许公开之前，你的选择将保持私密。")}</p>}
    {action?.options?.length ? <div className={styles.choiceRow}>{action.options.map((option) => { const value = optionValue(option); return <button key={value} className={`${styles.secondaryButton} ${choice === value ? styles.selectedChoice : ""}`} aria-pressed={choice === value} onClick={() => setChoice(value)} disabled={disabled}>{typeof option === "object" && (option.name || option.label) ? text(option.name || option.label, lang) : text(choiceLabels[value], lang) || text(roleMap[value]?.name, lang) || value}</button>; })}</div> : null}
    {((action && needsTarget) || voting || special) && <div className={styles.targetGrid}>{view.seats.filter((seat) => available.includes(seat.id)).map((seat) => <button key={seat.id} disabled={disabled} className={`${styles.targetButton} ${targets.includes(seat.id) ? styles.selectedTarget : ""}`} aria-pressed={targets.includes(seat.id)} onClick={() => select(seat.id)}><span>{view.seats.indexOf(seat) + 1}</span>{seat.name}{targets.includes(seat.id) && <Check size={15} />}</button>)}</div>}
    {(action || voting) && <div className={styles.actionButtons}><button className={styles.primaryButton} disabled={disabled || !!invalid} onClick={() => void submit()}><Check size={17} />{voting ? t("Submit vote", "提交投票") : t("Confirm action", "确认行动")}</button>{(action?.canSkip || voting) && <button className={styles.secondaryButton} disabled={disabled} onClick={() => void submit(true)}>{voting ? t("Abstain", "弃票") : t("Skip ability", "跳过技能")}</button>}</div>}
    {!action && !voting && daySpecial && <><p className={styles.hint}>{t("These abilities reveal your action publicly and cannot be undone.", "此技能将公开发动，无法撤销。")}</p><div className={styles.choiceRow}>{view.me?.canDuel && <button className={styles.secondaryButton} onClick={() => setSpecial("knightDuel")}>{t("Challenge a player", "选择决斗目标")}</button>}{view.me?.canExplode && <button className={styles.secondaryButton} onClick={() => setSpecial("wolfExplode")}>{t("Self-destruct", "发动自爆")}</button>}{view.me?.canPassBadge && <button className={styles.secondaryButton} onClick={() => setSpecial("passBadge")}>{t("Pass the sheriff badge", "移交警徽")}</button>}</div>{special && <button className={styles.dangerButton} disabled={disabled || ((special === "knightDuel" || special === "passBadge" || view.me?.roleId === "whiteWolfKing") && !targets.length)} onClick={() => void send({ type: special, targetId: targets[0] })}>{t("Confirm public ability", "确认公开发动技能")}</button>}</>}
  </div>;
}

function RoleLibrary({ lang, view, onClose }: { lang: Language; view: GameView | null; onClose: () => void }) {
  const [filter, setFilter] = useState("all");
  const [search, setSearch] = useState("");
  const t = (en: string, zh: string) => lang === "en" ? en : zh;
  return <Modal title={t("The role library", "角色图鉴")} onClose={onClose}><p className={styles.hint}>{catalogue.ruleset[lang]}</p><input className={styles.searchInput} placeholder={t("Find a role…", "搜索角色…")} value={search} onChange={(event) => setSearch(event.target.value)} aria-label={t("Search roles", "搜索角色")} /><div className={styles.filterTabs}>{[["all", t("All roles", "全部角色")], ["village", t("Village", "好人")], ["wolf", t("Werewolves", "狼人")], ["independent", t("Independent", "第三方")], ...(view ? [["deck", t("This deck", "本局配置")]] : [])].map(([id, label]) => <button key={id} className={filter === id ? styles.activeTab : ""} onClick={() => setFilter(id)}>{label}</button>)}</div><div className={styles.roleList}>{catalogue.roles.filter((role) => (filter === "all" || role.team === filter || filter === "deck" && view?.roleDeck.includes(role.id)) && `${role.name.en} ${role.name.zh}`.toLowerCase().includes(search.toLowerCase())).map((role) => <article key={role.id} className={styles.roleRow}><div className={`${styles.roleGlyph} ${role.team === "wolf" ? styles.wolfGlyph : ""}`}>{roleIcon(role, 25)}</div><div><h3>{role.name[lang]} <span>{role.name[lang === "en" ? "zh" : "en"]}</span>{view?.roleDeck.includes(role.id) && <small> ×{view.roleDeck.filter((id) => id === role.id).length}</small>}</h3><p>{role.description[lang]}</p></div></article>)}</div></Modal>;
}

function RoomSettings({ view, lang, disabled, send, onClose }: { view: GameView; lang: Language; disabled: boolean; send: (command: Command) => Promise<boolean>; onClose: () => void }) {
  const [settings, setSettings] = useState<Settings>(view.settings);
  const [deck, setDeck] = useState(view.roleDeck.length ? view.roleDeck : catalogue.presets.find((preset) => preset.id === String(view.seats.length))?.roles || catalogue.presets.find((preset) => preset.id === "12")!.roles);
  const t = (en: string, zh: string) => lang === "en" ? en : zh;
  const update = (key: string, value: unknown) => setSettings((current) => ({ ...current, [key]: value }));
  const changeCount = (id: string, amount: number) => setDeck((current) => amount > 0 ? current.length < 24 ? [...current, id] : current : current.filter((role, index) => role !== id || index !== current.indexOf(id)));
  return <Modal title={t("Set the table", "配置牌局")} onClose={onClose}><form onSubmit={async (event) => { event.preventDefault(); if (await send({ type: "updateSettings", settings: view.status === "lobby" ? settings : { autoAdvance: settings.autoAdvance, nightSeconds: settings.nightSeconds, daySeconds: settings.daySeconds, voteSeconds: settings.voteSeconds }, ...(view.status === "lobby" ? { roleDeck: deck } : {}) })) onClose(); }} className={styles.settingsForm}>
    {view.status === "lobby" && <><label>{t("Choose a starting deck", "选择预设角色配置")}<select value={catalogue.presets.find((preset) => JSON.stringify(preset.roles) === JSON.stringify(deck))?.id || "custom"} onChange={(event) => { const preset = catalogue.presets.find((preset) => preset.id === event.target.value); if (preset) setDeck(preset.roles); }}><option value="custom">{t("Custom deck", "自定义配置")}</option>{catalogue.presets.map((preset) => <option key={preset.id} value={preset.id}>{preset.name[lang]}</option>)}</select></label><div className={styles.deckHeading}><h3>{t("Role cards", "身份牌")}</h3><span>{deck.length} / {view.seats.length} {t("players", "位玩家")}</span></div><p className={styles.hint}>{t("Match one card to each player. Most village roles are unique; wolf and villager cards can repeat.", "每位玩家对应一张身份牌。大部分神职只能配置一张；狼人和平民可重复。")}</p><div className={styles.deckPicker}>{catalogue.roles.map((role) => { const count = deck.filter((id) => id === role.id).length; return <div key={role.id} className={styles.deckRow}><span>{roleIcon(role, 17)}{role.name[lang]}</span><div><button type="button" aria-label={`${t("Remove", "减少")} ${role.name[lang]}`} disabled={!count || disabled} onClick={() => changeCount(role.id, -1)}>−</button><span>{count}</span><button type="button" aria-label={`${t("Add", "增加")} ${role.name[lang]}`} disabled={disabled || deck.length >= 24 || count >= 1 && role.id !== "villager" && role.id !== "werewolf"} onClick={() => changeCount(role.id, 1)}>+</button></div></div>; })}</div></>}
    <h3>{t("Pace & moderation", "节奏与主持")}</h3>{view.status === "playing" && <p className={styles.hint}>{t("Saving timer settings restarts the current phase’s countdown.", "保存计时设置会重新开始当前阶段的倒计时。")}</p>}<label className={styles.toggleRow}><span>{t("Automatically advance phases", "自动推进阶段")}</span><input type="checkbox" checked={settings.autoAdvance} onChange={(event) => update("autoAdvance", event.target.checked)} /></label><p className={styles.hint}>{t("Automatic play pauses when someone disconnects. The host can resume or move a phase manually.", "自动模式遇到玩家断线会暂停。房主可继续或手动推进阶段。")}</p><div className={styles.timeSettings}>{[["nightSeconds", t("Night step (sec)", "夜间阶段（秒）")], ["daySeconds", t("Discussion (sec)", "发言（秒）")], ["voteSeconds", t("Voting (sec)", "投票（秒）")]].map(([key, label]) => <label key={key}>{label}<input type="number" min={15} max={900} required value={Number(settings[key])} onChange={(event) => update(key, Number(event.target.value))} /></label>)}</div>
    <h3>{t("House rules", "本局规则")}</h3><label>{t("Werewolf victory", "狼人获胜条件")}<select value={settings.winCondition} onChange={(event) => update("winCondition", event.target.value)} disabled={view.status !== "lobby"}><option value="edge">{t("Eliminate all villagers OR all special village roles", "屠边：消灭所有平民或所有神职")}</option><option value="all">{t("Eliminate the whole village", "屠城：消灭所有好人")}</option><option value="parity">{t("Equal or outnumber all opposition", "达到人数优势")}</option></select></label><label className={styles.toggleRow}><span>{t("Sheriff election enabled", "启用警长竞选")}</span><input type="checkbox" checked={settings.sheriff} onChange={(event) => update("sheriff", event.target.checked)} disabled={view.status !== "lobby"} /></label><label className={styles.toggleRow}><span>{t("Witch can save herself", "女巫允许自救")}</span><input type="checkbox" checked={settings.witchSelfSave} onChange={(event) => update("witchSelfSave", event.target.checked)} disabled={view.status !== "lobby"} /></label><label>{t("Guard + antidote on the same target", "同守同救")}<select value={settings.guardAntidote} onChange={(event) => update("guardAntidote", event.target.value)} disabled={view.status !== "lobby"}><option value="save">{t("Target survives", "目标存活")}</option><option value="kill">{t("Target dies", "目标死亡")}</option></select></label><div className={styles.modalActions}><button type="button" className={styles.secondaryButton} onClick={onClose}>{t("Cancel", "取消")}</button><button type="submit" className={styles.primaryButton} disabled={disabled}>{t("Save settings", "保存设置")}</button></div>
  </form></Modal>;
}

function PeopleManager({ view, lang, disabled, send, onClose }: { view: GameView; lang: Language; disabled: boolean; send: (command: Command) => Promise<boolean>; onClose: () => void }) {
  const [name, setName] = useState("");
  const [replacement, setReplacement] = useState<Record<string, string>>({});
  const [confirmSeat, setConfirmSeat] = useState("");
  const t = (en: string, zh: string) => lang === "en" ? en : zh;
  return <Modal title={t("Around the table", "座位与玩家")} onClose={onClose}><p className={styles.hint}>{t("Invite with room code", "邀请房间码")} <strong>{view.code}</strong> · {t("Rejoining players keep their role when you replace their existing seat.", "将重连玩家接替至原座位，可保留其身份与进度。")}</p>
    {view.isHost && !!view.requests?.length && <section className={styles.joinRequests}><h3>{t("Waiting for your approval", "等待你的批准")}</h3>{view.requests.map((request) => <div key={request.id} className={styles.joinRequest}><strong>{request.name}</strong><label>{t("Seat assignment", "安排座位")}<select value={replacement[request.id] || ""} onChange={(event) => setReplacement((current) => ({ ...current, [request.id]: event.target.value }))}><option value="">{view.status === "lobby" ? t("Add as a new player", "作为新玩家加入") : t("Select a seat to replace", "选择要接替的座位")}</option>{view.seats.filter((seat) => !seat.isHost).map((seat) => <option key={seat.id} value={seat.id}>{view.seats.indexOf(seat) + 1}. {seat.name} · {seat.connected ? t("online", "在线") : t("offline", "离线")}</option>)}</select></label>{replacement[request.id] && view.seats.find((seat) => seat.id === replacement[request.id])?.connected && <p className={styles.warningText}>{t("This player is online. Approving replaces their access immediately.", "此玩家仍在线，批准后将立即替换其访问权限。")}</p>}<div className={styles.actionButtons}><button className={styles.primaryButton} disabled={disabled || view.status !== "lobby" && !replacement[request.id]} onClick={() => void send({ type: "approveJoin", requestId: request.id, replaceSeatId: replacement[request.id] || undefined })}><Check size={15} />{t("Approve", "批准")}</button><button className={styles.secondaryButton} disabled={disabled} onClick={() => void send({ type: "rejectJoin", requestId: request.id })}>{t("Decline", "拒绝")}</button></div></div>)}</section>}
    <div className={styles.peopleList}>{view.seats.map((seat, index) => <div key={seat.id} className={styles.personRow}><span className={styles.personNumber}>{index + 1}</span><div><strong>{seat.name}{seat.isHost && <Crown size={14} />}</strong><small>{seat.connected && seat.occupied ? t("Connected", "在线") : t("Seat retained · waiting to reconnect", "座位保留 · 等待重连")}</small></div>{view.isHost && !seat.isHost && <div className={styles.personActions}>{view.phase.kind === "day" && seat.alive && <button className={styles.iconButton} disabled={disabled || view.phase.paused} title={t("Give the floor", "安排发言")} onClick={() => void send({ type: "setSpeaker", seatId: seat.id })}><SpeakerHigh size={18} /></button>}<button className={styles.iconButton} disabled={disabled || !seat.occupied} title={t("Transfer hosting", "移交房主")} onClick={() => setConfirmSeat(`host:${seat.id}`)}><Crown size={18} /></button><button className={styles.iconButton} disabled={disabled} title={t("Remove player", "移除玩家")} onClick={() => setConfirmSeat(`remove:${seat.id}`)}><Trash size={18} /></button></div>}{confirmSeat.endsWith(`:${seat.id}`) && <div className={styles.inlineConfirm}><p>{confirmSeat.startsWith("host:") ? t(`Transfer host controls to ${seat.name}? Your host access will end.`, `将房主移交给 ${seat.name}？你将失去房主权限。`) : view.status === "lobby" ? t(`Remove ${seat.name} from this room?`, `将 ${seat.name} 移出房间？`) : t(`Remove ${seat.name}'s access? Their role stays alive and can be reassigned.`, `移除 ${seat.name} 的访问权限？其角色仍然存活，可安排他人接替。`)}</p><button className={styles.dangerButton} disabled={disabled} onClick={async () => { if (await send({ type: confirmSeat.startsWith("host:") ? "transferHost" : "removeSeat", seatId: seat.id })) setConfirmSeat(""); }}>{t("Confirm", "确认")}</button><button className={styles.textButton} onClick={() => setConfirmSeat("")}>{t("Cancel", "取消")}</button></div>}</div>)}</div>
    {view.isHost && view.status === "lobby" && <form className={styles.addPlayerForm} onSubmit={async (event) => { event.preventDefault(); if (await send({ type: "addSeat", name: name.trim() })) setName(""); }}><label>{t("Reserve a named seat", "预留具名座位")}<input value={name} onChange={(event) => setName(event.target.value)} required maxLength={24} placeholder={t("Player name", "玩家名字")} /></label><button className={styles.secondaryButton} disabled={disabled || !name.trim()}><Plus size={17} />{t("Add seat", "添加座位")}</button><p className={styles.hint}>{t("Before the game starts, a player joining with this exact name takes the reserved seat automatically. Other players join new seats.", "游戏开始前，玩家使用完全相同的名字加入即可自动入座；其他名字的玩家会加入新座位。")}</p></form>}
  </Modal>;
}

function ChatPanel({ view, lang, disabled, send }: { view: GameView; lang: Language; disabled: boolean; send: (command: Command) => Promise<boolean> }) {
  const [message, setMessage] = useState("");
  const [channel, setChannel] = useState("public");
  const t = (en: string, zh: string) => lang === "en" ? en : zh;
  const allowed = !view.me ? [] : !view.me.alive && view.status === "playing" ? ["dead"] : view.phase.kind === "night" ? view.me.team === "wolf" && view.me.roleId !== "hiddenWolf" && view.me.roleId !== "gargoyle" ? ["wolves"] : [] : ["public"];
  const activeChannel = allowed.includes(channel) ? channel : allowed[0] || "public";
  return <><div className={styles.chatChannels}>{allowed.map((item) => <button key={item} className={activeChannel === item ? styles.activeTab : ""} onClick={() => setChannel(item)}>{item === "wolves" ? t("Wolf pack", "狼队频道") : item === "dead" ? t("Eliminated players", "出局玩家频道") : t("The village", "公共频道")}</button>)}</div><div className={styles.chatMessages}>{view.messages?.filter((item) => item.channel === activeChannel).slice(-60).map((item) => <div key={item.id}><strong>{item.name || view.seats.find((seat) => seat.id === item.seatId)?.name}</strong><p>{item.text}</p></div>)}{!view.messages?.some((item) => item.channel === activeChannel) && <p className={styles.emptyLog}>{t("No messages yet. Choose your words carefully.", "暂无消息。每一句话，都可能是线索。")}</p>}</div><form className={styles.chatForm} onSubmit={async (event) => { event.preventDefault(); if (await send({ type: "chat", text: message.trim(), channel: activeChannel })) setMessage(""); }}><input value={message} onChange={(event) => setMessage(event.target.value)} maxLength={500} required disabled={!allowed.length} aria-label={t("Chat message", "聊天消息")} placeholder={!allowed.length ? t("Please stay quiet during the night", "夜间请保持安静") : t("Say something to the table…", "说出你的想法…")} /><button className={styles.primaryButton} disabled={disabled || !allowed.length || !message.trim()}><ArrowRight size={20} /><span>{t("Send", "发送")}</span></button></form></>;
}

function Replay({ view, lang }: { view: GameView; lang: Language }) {
  const t = (en: string, zh: string) => lang === "en" ? en : zh;
  const seatName = (id: string) => view.seats.find((seat) => seat.id === id)?.name || id;
  return <section className={styles.replayPanel}><h2><Eye size={18} />{t("Behind the secrets", "秘密揭晓")}</h2><p className={styles.hint}>{t("The complete action record is revealed only after the game ends.", "完整行动记录仅在游戏结束后公开。")}</p>{view.replay?.map((round, index) => <details key={index} className={styles.replayRound}><summary>{round.type === "night" ? t(`Night ${round.night}`, `第 ${round.night} 夜`) : `${t(`Day ${round.day}`, `第 ${round.day} 天`)} · ${round.kind === "sheriff" ? t("Sheriff election", "警长竞选") : t("Exile vote", "放逐投票")}`}</summary>{round.type === "night" ? <><div className={styles.replayRows}>{Object.entries(round.actions).flatMap(([step, actions]) => Object.entries(actions).map(([id, action]) => <div key={`${step}:${id}`}><span>{text(roleMap[step]?.name || stepLabels[step], lang) || step}</span><strong>{seatName(id)}</strong><p>{action.skip ? t("Skipped", "跳过") : `${action.ability ? text(choiceLabels[action.ability], lang) || action.ability : action.choice ? text(choiceLabels[action.choice], lang) || action.choice : t("Selected", "选择")} ${action.targetIds?.length ? action.targetIds.map(seatName).join(" · ") : action.targetId ? seatName(action.targetId) : ""}`}</p></div>))}</div><p className={styles.hint}>{t("Eliminated:", "出局：")} {round.eliminatedSeatIds?.length ? round.eliminatedSeatIds.map(seatName).join(" · ") : t("No one", "无人")}</p></> : <div className={styles.replayRows}>{Object.entries(round.votes).map(([id, target]) => <div key={id}><strong>{seatName(id)}</strong><ArrowRight size={13} /><p>{target ? seatName(target) : t("Abstained", "弃票")}</p></div>)}</div>}</details>)}</section>;
}
